"""Regression test: every email HTML body (tables + text) generated by the app must be
normalised into a mail-client-safe structure before it is previewed / copied.

Run:  python3 tests/test_email_bodies.py
"""
import os
import pathlib
import re
from playwright.sync_api import sync_playwright

WS = pathlib.Path(__file__).resolve().parent.parent

# this sandbox ships a newer chromium build than the pinned playwright expects
CHROME_CANDIDATES = [
    "/root/.cache/ms-playwright/chromium-1234/chrome-linux64/chrome",
    "/root/.cache/ms-playwright/chromium_headless_shell-1234/"
    "chrome-headless-shell-linux64/chrome-headless-shell",
]
EXEC = next((c for c in CHROME_CANDIDATES if os.path.exists(c)), None)

BODIES = {
    # exact markup from js/common-buttons.js -> OF.sendQcReport (text only)
    "qc-report": "<html><body style='font-family:Times New Roman; font-size:11pt;'>"
        "<p><strong><span style='color:Brown;font-size:15pt;'>Dear Team,</span></strong></p>"
        "<p><strong><span style='color:black;font-size:15pt;'>Please make the </span>"
        "<span style='color:red; background-color:yellow;font-size:20pt;'>Quality Report</span>"
        "<span style='color:black;font-size:15pt;'> for all the items in below order.</span></strong></p>"
        "<p><strong><span style='color:blue; font-size:25pt;'>MV TEST VOYAGER</span></strong></p>"
        "</body></html>",
    # exact markup from js/common-buttons.js -> OF.sendWaterOrder (class-based styles + table)
    "water-order": "<html><head><style>"
        "body,p{font-family:'Times New Roman',serif;font-size:15.5pt;}"
        "table{font-size:inherit;border-collapse:collapse;}th{background:#f2f2f2;text-align:center;}td{padding:5px;}"
        ".center{text-align:center;}.highlight{font-weight:bold;color:black;background-color:#ADD8E6;}"
        "</style></head><body>"
        "<p class='larger-text'>Dear Faisal,</p>"
        "<p class='larger-text'>Please see below order for water requirement and please stage.</p>"
        "<p><strong>Vessel:</strong> <span class='highlight'>MV OCEAN STAR</span></p>"
        "<p><strong>Sales Order Number:</strong> <span class='highlight'>SO-9001</span></p>"
        "<table border='1' cellspacing='0'><tr>"
        "<th width='15%'>Item Code</th><th width='60%'>Description</th><th width='10%'>Quantity</th><th width='15%'>Unit</th></tr>"
        "<tr><td class='center'><b>0135054</b></td>"
        "<td>WATER, MINERAL, 1.5 LTR X 12 BTL PER CASE (FUJAIRAH)</td>"
        "<td class='center'>50</td><td class='center'>CS</td></tr></table></body></html>",
    # exact markup produced by js/tab1.js -> OF.sendEtaEmail (inline-styled table)
    "eta-email": "<html><head><style>"
        "body{margin:0;padding:0;background-color:#f5f7fa;}"
        ".email-container{margin:0 auto;}.email-content{background-color:lightblue;padding:0px;}"
        "h1{color:#8B0000;font-size:25pt;font-family:'Kristen ITC','Times New Roman';}"
        "p{color:#FF00FF;line-height:1;font-family:'Times New Roman';font-size:15pt;margin:5px 0;}"
        "</style></head><body><div class='email-container'><div class='email-content'>"
        "<h1 style='color:#8B0000;'>Vessel Schedule Update</h1>"
        "<p>Dear Team,</p>"
        "<p>Please advise the exact <b>ETA</b> for the below vessels with <b>REMARKS</b>.</p>"
        "<table style='border-collapse: collapse; font-family: Arial, sans-serif;'>"
        "<thead><tr style='background-color:#40E0D0;color:#FF00FF;'>"
        "<th style='padding:12px 8px;border:6px solid #E0E0E0;text-align:center;'>SR#</th>"
        "<th style='padding:12px 8px;border:6px solid #E0E0E0;text-align:center;'>VESSEL NAME</th>"
        "<th style='padding:12px 8px;border:6px solid #E0E0E0;text-align:center;'>PORT</th>"
        "</tr></thead><tbody>"
        "<tr><td style='padding:6px 12px;border:6px solid #E0E0E0;text-align:center;font-weight:bold;'>1</td>"
        "<td style='padding:6px 12px;border:6px solid #E0E0E0;font-weight:bold;'>MV AL RIFFA</td>"
        "<td style='padding:6px 12px;border:6px solid #E0E0E0;text-align:center;font-weight:bold;color:#0288D1;'>JEBEL ALI</td>"
        "</tr></tbody></table></div></div></body></html>",
    # exact markup produced by js/tab2.js -> createReorderHtmlTable + htmlBody
    "reorder": "<html><head><style>body{font-family:'Times New Roman',serif;font-size:12pt;margin:0;padding:10px;}</style></head><body>"
        "<p>Dear Purchase team,</p>"
        "<p>Please arrange below items for sales order# <strong>SO-777</strong> "
        "<span style='color:red;font-weight:bold;'>Loading</span> <strong style='color:red;'>14th October, 2026</strong></p>"
        "<table border='3.3' cellpadding='5' cellspacing='2' style='border-collapse:collapse;font-family:Times New Roman;font-size:14px;width:auto;border:3.3px solid #4472C4;'>"
        "<tr style='background-color:#4472C4;color:white;font-weight:bold;'>"
        "<td style='border:3.3px solid #C47444;text-align:center;padding:5px;'>SR NO#</td>"
        "<td style='border:3.3px solid #C47444;text-align:center;padding:5px;'>ITEM CODE#</td>"
        "<td style='border:3.3px solid #C47444;text-align:center;padding:5px;'>ITEM#</td></tr>"
        "<tr style='background-color:#FFFFFF;font-weight:bold;'>"
        "<td style='border:3.3px solid #C4D1E0;text-align:center;padding:5px;'>1</td>"
        "<td style='border:3.3px solid #C4D1E0;text-align:center;padding:5px;'>0135054</td>"
        "<td style='border:3.3px solid #C4D1E0;text-align:left;padding:5px;'>WATER, MINERAL, 1.5LTR X12</td></tr>"
        "<tr style='background-color:#E9E9E9;font-weight:bold;'>"
        "<td style='border:3.3px solid #C4D1E0;text-align:center;padding:5px;'>2</td>"
        "<td style='border:3.3px solid #C4D1E0;text-align:center;padding:5px;'>0110221</td>"
        "<td style='border:3.3px solid #C4D1E0;text-align:left;padding:5px;'>BREAD, WHOLE WHEAT, 500G</td></tr>"
        "</table></body></html>",
    # exact markup produced by js/tab3.js inquiry batches
    "inquiry": "<html><body style='font-family:Calibri;font-size:11pt;'>"
        "<p>Dear Al Noor Trading,</p>"
        "<p>Please quote your best price and availability against Reference <b>Q-2026-14</b>:</p>"
        "<table border='1' cellpadding='4' style='border-collapse:collapse;font-family:Calibri;font-size:11pt;'>"
        "<tr style='background:#4472C4;color:#fff;'><th>Item Code</th><th>Description</th><th>Qty</th></tr>"
        "<tr><td>0135054</td><td style=\"text-align:left\">WATER, MINERAL 1.5L</td><td>100</td></tr>"
        "</table>"
        "<p style='color:#C00000;font-weight:bold;'>Kindly respond by 10/14/2026, 5:30:00 PM.</p>"
        "<p>Note: Attach your signed quotation Excel file when replying.<br/>Best Regards,<br/>Oceanfair Ship Stores</p>"
        "</body></html>",
}

JS_HARNESS = """
async (bodies) => {
  const out = {};
  for (const key of Object.keys(bodies)) {
    const html = OF.buildEmailHtml(bodies[key]);
    out[key] = { html: html, text: OF.htmlToText(html) };
  }
  return out;
}
"""


def main():
    failures = []
    with sync_playwright() as p:
        browser = p.chromium.launch(executable_path=EXEC, args=["--no-sandbox"])
        page = browser.new_page()
        errors = []
        page.on("pageerror", lambda e: errors.append(str(e)))
        page.goto("file://" + str(WS / "index.html"))
        assert page.evaluate("typeof OF !== 'undefined'"), "core.js did not load"

        res = page.evaluate(JS_HARNESS, BODIES)
        for key, r in res.items():
            html, text = r["html"], r["text"]
            cells = re.findall(r"<t[dh][^>]*>", html)
            if "<style" in html:
                failures.append(f"{key}: <style> block survived normalisation")
            if re.search(r"\sclass\s*=", html):
                failures.append(f"{key}: class attributes survived (ignored by mail clients)")
            unstyled = [c for c in cells if "style=" not in c]
            if unstyled:
                failures.append(f"{key}: {len(unstyled)} cell(s) without inline style")
            if "font-family" not in html:
                failures.append(f"{key}: no font-family in output")
            if not text.strip():
                failures.append(f"{key}: plain-text version is empty")
            if "mailto:" in html:
                failures.append(f"{key}: unexpected mailto inside body")
            print(f"[{key}] tables={html.count('<table')} cells={len(cells)} "
                  f"html={len(html)} chars, text={len(text)} chars")

        # the plain-text version must contain the table content in an aligned form
        txt = res["reorder"]["text"]
        for needle in ("SR NO#", "ITEM CODE#", "WATER, MINERAL, 1.5LTR X12", "BREAD, WHOLE WHEAT, 500G"):
            if needle not in txt:
                failures.append(f"reorder plain text lost '{needle}'")

        # preview window wiring: openMail must produce a working preview + toolbar
        page.evaluate("""() => {
          window.__opened = null; window.__loc = null;
          const origOpen = window.open;
          window.open = function () {
            const w = origOpen.call(window, '', '_blank');
            window.__opened = w; return w;
          };
        }""")
        page.evaluate("""() => OF.openMail({
            to: 'a@b.com; c@d.com', cc: 'e@f.com', subject: 'TEST SUBJECT',
            htmlBody: %s})""" % ("%r" % BODIES["water-order"]))
        page.wait_for_timeout(400)
        info = page.evaluate("""() => {
          const w = window.__opened;
          if (!w) return { ok:false, why:'no preview window' };
          const ids = ['of-copy-html','of-dl-html','of-copy-text'];
          const missing = ids.filter(i => !w.document.getElementById(i));
          return {
            ok: missing.length === 0 && !!w.document.querySelector('table'),
            missing: missing,
            titleCells: w.document.querySelectorAll('td,th').length,
            hasStyleTag: /<style/i.test(w.document.body.innerHTML),
            text: (w.document.body.innerText || '').slice(0, 200)
          };
        }""")
        print("openMail preview:", info)
        if not info.get("ok"):
            failures.append(f"openMail preview incomplete: {info}")

        browser.close()

    print("\n--- sample normalised reorder HTML ---")
    print(res["reorder"]["html"][:900])
    print("\n--- sample plain text (mailto body) ---")
    print(res["reorder"]["text"])

    if errors:
        failures.append("JS page errors: " + "; ".join(errors))
    if failures:
        print("\nFAILED:")
        for f in failures:
            print(" -", f)
        raise SystemExit(1)
    print("\nALL CHECKS PASSED")


main()
